<?php
 declare(strict_types=1);
function ofaOrderHtml(array $order,string $review,string $receipt,bool $slip): string {
 $h=static function($s){return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');};
 $scale=$order['currency']==='THB'?100:1;
 $money=static function($n)use($scale,$order,$h){return number_format((float)$n/$scale,$scale===100?2:0).' '.$h($order['currency']);};
 $rows='';foreach(json_decode($order['items'],true)?:[] as $it){$rows.='<tr><td style="padding:16px 0;border-bottom:1px solid #344360"><strong style="color:#ffffff;font-size:16px">'.$h($it['title']).'</strong><br><span style="color:#bbc8df;font-size:13px">'.$h($it['type']).' &middot; Qty '.$h($it['quantity']).'</span></td><td align="right" style="padding:16px 0;border-bottom:1px solid #344360;color:#d6caff;white-space:nowrap">'.$money($it['unit']*$it['quantity']).'<br><small style="color:#a8b6ce">'.$money($it['unit']).' each</small></td></tr>';}
 return '<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;background:#0c1425;font-family:Arial,sans-serif;color:#edf2ff"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#0c1425"><tr><td align="center" style="padding:24px 12px"><table role="presentation" width="600" cellspacing="0" cellpadding="0" style="width:100%;max-width:600px;background:#17243b;border:1px solid #344360;border-radius:18px"><tr><td style="padding:26px;background:#223453;border-radius:18px 18px 0 0"><span style="color:#b9c9ff;font-size:12px;letter-spacing:2px">ONE FOR ALL GAME SERVICE</span><h1 style="font-size:26px;margin:12px 0;color:#ffffff">A new order is here</h1><span style="color:#ffd28b;font-size:14px">PAYMENT AWAITING VERIFICATION</span></td></tr><tr><td style="padding:24px"><p style="color:#aabbd4;margin:0 0 6px">ORDER ID</p><div style="font:700 18px monospace;color:#d6caff;overflow-wrap:anywhere">'.$h($order['id']).'</div><p style="color:#aabbd4;font-size:13px">Server-checked prices &middot; Payment still requires your review.</p><table width="100%" cellspacing="0" cellpadding="0">'.$rows.'</table><table width="100%" cellpadding="6" style="margin-top:16px;color:#edf2ff"><tr><td>Subtotal</td><td align="right">'.$money($order['subtotal']).'</td></tr><tr><td>Discount</td><td align="right" style="color:#a7ebd9">−'.$money($order['discount']).'</td></tr><tr><td style="font-size:21px;font-weight:bold">Total</td><td align="right" style="font-size:21px;font-weight:bold;color:#b9c9ff">'.$money($order['total']).'</td></tr></table><p style="color:#bbc8df">'.($slip?'Payment slip attached to this email.':'No payment slip attached.').'</p><p style="margin:26px 0"><a href="'.$h($review).'" style="display:inline-block;background:#bac8ff;color:#101a30;padding:15px 22px;border-radius:10px;font-weight:bold;text-decoration:none">Open order / Copy details</a></p><p style="color:#ffd28b;font-size:13px;line-height:1.6">Seller-only link. Do not forward this email. Opening the order does not approve payment. Verify the actual incoming transfer before approving.</p><h3 style="font-size:14px;color:#b9c9ff">Customer-submitted receipt</h3><pre style="white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.6 Arial,sans-serif;color:#bbc8df">'.$h($receipt).'</pre></td></tr></table></td></tr></table></body></html>';
}
function ofaOrderAlternative(string $plain,string $html): array {
 $b='ofa_alt_'.bin2hex(random_bytes(12));
 $body='';foreach(['text/plain'=>$plain,'text/html'=>$html] as $type=>$data){$body.='--'.$b."\r\nContent-Type: ".$type."; charset=UTF-8\r\nContent-Transfer-Encoding: base64\r\n\r\n".chunk_split(base64_encode($data),76,"\r\n");}
 return ['type'=>'multipart/alternative; boundary="'.$b.'"','body'=>$body.'--'.$b."--\r\n"];
}
